// src-tauri/src/main.rs
use tauri::Manager;

// 一个“命令”：前端 JS 可以直接调用它
#[tauri::command]
fn read_config() -> String {
    std::fs::read_to_string("config.json")
        .unwrap_or_else(|_| "{}".into())
}

fn main() {
    tauri::Builder::default()
        .invoke_handler(tauri::generate_handler![read_config])
        .run(tauri::generate_context!())
        .expect("启动失败");
}
